import json
with open('/app/resources/treasury_bulletin_1940_03.json', 'r') as f:
    data = json.load(f)

# Look for exchange rate or currency data
def search_elements(elements, keyword):
    for el in elements:
        if 'content' in el and el['content']:
            if keyword.lower() in str(el['content']).lower():
                print(el['content'][:200] if len(str(el['content'])) > 200 else el['content'])
        if 'elements' in el:
            search_elements(el['elements'], keyword)

search_elements(data.get('document', {}).get('elements', []), '1941')
